mapper.select:
SELECT oi.id AS item_id, oi.order_id, oi.merchant_id, COALESCE(m.merchant_name, '默认店铺') AS merchant_name, oi.product_image AS goods_url, oi.product_name AS title, oi.sku_specs AS type, oi.price, oi.quantity AS number FROM biz_order_item oi LEFT JOIN biz_merchant m ON oi.merchant_id = m.id WHERE oi.order_id IN
#{orderId}
ORDER BY oi.order_id, oi.id
